SELECT FUND_NAME AS `基金名称`, FUND_SYMBOL AS `基金代码`, YEAR AS `年度`, ROUND(YIELD, 2) AS `年度收益率(%)`, ROUND(ANNUAL_YIELD, 2) AS `年化收益率(%)`, MAX_DRAWBACK AS `最大回撤`, SHARPE AS `夏普比率` FROM FUND_STATISTICS_YEAR WHERE FUND_NAME LIKE '%中欧%' AND YEAR = 2025 AND HISVALID = 1 AND YIELD IS NOT NULL ORDER BY YIELD DESC LIMIT 1;
